<script>
document.getElementById('teacher-grade').closest('label').childNodes[0].nodeValue='Assigned grade';
const placementOptions=<?= json_encode($placement) ?>,subjectOptions=<?= json_encode(teacherSubjects()) ?>,savedSection=<?= json_encode($teacher['SECTION']) ?>,savedStrand=<?= json_encode($teacher['STRAND']??'') ?>,savedSubject=<?= json_encode($teacher['SUBJECT']??'') ?>,gradeSelect=document.getElementById('teacher-grade'),assignmentSelect=document.getElementById('teacher-assignment'),assignmentLabel=document.getElementById('assignment-label'),sectionSelect=document.getElementById('teacher-section');
function setOptions(select,placeholder,items,value=''){select.innerHTML='';select.add(new Option(placeholder,''));items.forEach(item=>select.add(new Option(item,item,item===value,item===value)))}
function updateTeacherPlacement(restore=false){const grade=gradeSelect.value,senior=grade==='11'||grade==='12';assignmentLabel.textContent=senior?'Strand assigned':'Subject assigned';assignmentSelect.name=senior?'strand':'subject';assignmentSelect.disabled=!grade;setOptions(assignmentSelect,grade?(senior?'Choose a strand':'Choose a subject'):'Choose a grade first',senior?['Techpro','Academic']:subjectOptions,restore?(senior?savedStrand:savedSubject):'');if(!grade){setOptions(sectionSelect,'Choose a grade first',[]);sectionSelect.disabled=true;return}if(senior){updateTeacherSections(restore)}else{setOptions(sectionSelect,'Choose a section',placementOptions[grade]||[],restore?savedSection:'');sectionSelect.disabled=false}}
function updateTeacherSections(restore=false){const sections=placementOptions[gradeSelect.value]?.[assignmentSelect.value]||[];setOptions(sectionSelect,assignmentSelect.value?'Choose a section':'Choose a strand first',sections,restore?savedSection:'');sectionSelect.disabled=!assignmentSelect.value}
gradeSelect.onchange=()=>updateTeacherPlacement();assignmentSelect.onchange=()=>updateTeacherSections();updateTeacherPlacement(true);document.getElementById('open-delete-teacher').onclick=()=>document.getElementById('delete-teacher-modal').classList.replace('hidden','flex');document.getElementById('cancel-delete-teacher').onclick=()=>document.getElementById('delete-teacher-modal').classList.replace('flex','hidden');document.getElementById('confirm-delete-teacher').onclick=()=>document.getElementById('delete-teacher-form').submit();
</script><?php adminFoot(); ?>
